import { groupPresets, type Preset } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function throwsNamed(fn: () => unknown, name: 'TypeError' | 'RangeError'): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof Error && error.name === name) return;
    throw new Error(`expected ${name}`);
  }
  throw new Error(`expected ${name}`);
}

const empty = groupPresets([]);
equal(empty, { available: [], withdrawn: [] }, 'empty input');
assert(empty.available !== empty.withdrawn, 'empty groups must be distinct arrays');

const input: readonly Preset[] = [
  { id: 'b', label: 'same', status: 'available' },
  { id: 'w2', label: 'beta', status: 'withdrawn' },
  { id: 'z', label: 'a', status: 'available' },
  { id: 'a', label: 'same', status: 'available' },
  { id: 'A', label: 'Z', status: 'available' },
  { id: 'w1', label: 'Alpha', status: 'withdrawn' },
];
const snapshot = JSON.stringify(input);
const grouped = groupPresets(input);
equal(grouped.available.map(item => item.id), ['A', 'z', 'a', 'b'], 'code-unit label and id ordering');
equal(grouped.withdrawn.map(item => item.id), ['w1', 'w2'], 'withdrawn ordering');
assert(JSON.stringify(input) === snapshot, 'input content must not change');
for (const returned of [...grouped.available, ...grouped.withdrawn]) {
  const original = input.find(item => item.id === returned.id);
  assert(returned !== original, `preset ${returned.id} must be copied`);
}
grouped.available[0].label = 'changed';
assert(input[4].label === 'Z', 'mutating output must not affect input');

throwsNamed(() => groupPresets([{ id: '   ', label: 'valid', status: 'available' }]), 'TypeError');
throwsNamed(() => groupPresets([{ id: 'valid', label: '\t\n', status: 'withdrawn' }]), 'TypeError');
throwsNamed(() => groupPresets([
  { id: 'same-id', label: 'one', status: 'available' },
  { id: 'same-id', label: 'two', status: 'withdrawn' },
]), 'RangeError');

